from pathlib import Path
import json
from html import escape
root=Path(__file__).parent
manifest=root/'.openai/hosting.json'
m=json.loads(manifest.read_text());m['static']={'directory':'dist'};manifest.write_text(json.dumps(m,indent=2)+'\n')
origin='https://revwinn-connected-studio.zaidarif886.chatgpt.site'
pages={'':('Your business. Better connected.','Marketing, websites, software and automation. Revwin Studio brings the digital pieces of your business together.'),'services':('Services','Explore digital marketing, website design, software, automation, creative and digital strategy.'),'work':('Our work','Explore clearly labeled Revwin Studio concept projects for websites, brand experiences and connected operations.'),'about':('About the studio','A business-first approach to design, technology and connected digital systems.'),'process':('Our process','From discovery and planning to design, development, testing, launch and improvement.'),'contact':('Start a project','Prepare a project inquiry for Revwin Studio. Share what you want to build or improve.'),'work/evergreen':('Evergreen — Website concept','A self-initiated concept for a landscape studio. Editorial design, responsive structure and a clear enquiry journey.'),'work/relay':('Relay — Operations concept','A self-initiated interface concept for connected enquiry management and daily operations.'),'privacy':('Privacy notice','How this website preview handles project briefs, fonts and hosting.'),'terms':('Website terms','Information about the website preview, concept work and project scoping.')}
for route,(title,desc) in pages.items():
    target=root/'dist'/route;target.mkdir(parents=True,exist_ok=True)
    url=origin+'/'+(route+'/' if route else '')
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#2563eb"><title>{escape(title)} | Revwin Studio</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(title)} | Revwin Studio"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{origin}/social.svg"><link rel="icon" href="/assets/revwin-logo.png" type="image/png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/refinements.css"><link rel="stylesheet" href="/studio-theme.css"><script defer src="/app.js"></script><script defer src="/services-scroll.js"></script></head><body><div id="app"></div><noscript><main style="max-width:800px;margin:80px auto;padding:24px;font-family:sans-serif"><h1>{escape(title)}</h1><p>{escape(desc)}</p><p>Please enable JavaScript for interactive content and the project brief form.</p><a href="/">Home</a> · <a href="/services/">Services</a> · <a href="/contact/">Contact</a></main></noscript></body></html>'''
    (target/'index.html').write_text(html)
(root/'dist/404.html').write_text((root/'dist/index.html').read_text().replace('<title>Your business. Better connected.','<title>Page not found.'))
(root/'dist/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#2563eb"/><path d="M17 47V17h20c15 0 21 17 9 24l11 10H41L30 40v11H17Zm13-20v6h8c5 0 5-6 0-6h-8Z" fill="white"/></svg>')
(root/'dist/social.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><rect width="1200" height="630" fill="#f5f8fc"/><text x="80" y="110" font-size="36" font-family="sans-serif" font-weight="bold" fill="#0b1220">revwinn STUDIO</text><text x="80" y="300" font-size="90" font-family="sans-serif" fill="#0b1220">Your business.</text><text x="80" y="410" font-size="90" font-family="sans-serif" fill="#2563eb">Better connected.</text><text x="80" y="550" font-size="24" font-family="sans-serif" fill="#526176">Strategy. Design. Technology. Growth.</text></svg>')
(root/'dist/robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
(root/'dist/sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+origin+'/'+(r+'/' if r else '')+'</loc></url>' for r in pages)+'</urlset>')
(root/'dist/_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n')
print(f'Generated {len(pages)} pages plus 404, sitemap, metadata and assets.')
